CREATE TABLE IF NOT EXISTS player_registration_slots (player_id uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES academy_sessions(id) ON DELETE CASCADE, PRIMARY KEY (player_id, session_id));
CREATE TABLE IF NOT EXISTS player_schedule_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), player_id uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES academy_sessions(id) ON DELETE CASCADE, session_date date NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK (status IN ('Present','Absent','Pending')), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(player_id, session_id, session_date));